-- Matriz MVP: initial schema (CMP-12 Data Storage).
-- Source of truth: docs/database.md (entities, attributes, keys, R-01 to R-18, BR-xx, DA-xx).
--
-- Representation choices (flagged in the setup report, not decisions about behaviour):
--   * ids are UUIDs generated by PostgreSQL (format not decided by API-A4).
--   * "string" and "text" are both stored as TEXT; maximum lengths are pending (PD-04).
--   * enums are TEXT with a CHECK constraint, stored as upper-case codes.
--   * datetimes are TIMESTAMPTZ.
-- Delete behaviour: only DA-05 (deleting a task deletes its comments and notifications) cascades.
-- Every other foreign key uses NO ACTION, so a referenced row cannot be deleted (NFR-03).
-- Rules that span several rows (BR-04, BR-09, BR-13, BR-18) are enforced by the modules, not here.

-- Account (CMP-01). password_hash: added with the project decision-maker's approval on 2026-11-12;
-- deviates from DA-08 until TD-03 is recorded. Stores a BCrypt hash, never the password.
CREATE TABLE account (
    account_id    UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    name          TEXT NOT NULL,                      -- DA-02
    email         TEXT NOT NULL,
    password_hash TEXT NOT NULL,
    CONSTRAINT account_email_uk UNIQUE (email)        -- DA-01
);

-- Workspace (CMP-02)
CREATE TABLE workspace (
    workspace_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    name         TEXT NOT NULL                         -- DA-02
);

-- Member (CMP-02): resolves Account and Workspace (R-01, R-02).
CREATE TABLE member (
    member_id    UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    workspace_id UUID NOT NULL REFERENCES workspace (workspace_id),
    account_id   UUID NOT NULL REFERENCES account (account_id),
    role         TEXT NOT NULL,
    status       TEXT NOT NULL DEFAULT 'ACTIVE',
    CONSTRAINT member_workspace_account_uk UNIQUE (workspace_id, account_id),   -- BR-05
    CONSTRAINT member_role_ck CHECK (role IN
        ('WORKSPACE_ADMINISTRATOR', 'PROJECT_MANAGER', 'TEAM_MEMBER', 'VIEWER')),  -- BR-03
    CONSTRAINT member_status_ck CHECK (status IN ('ACTIVE', 'DEACTIVATED'))
);

-- Invitation (CMP-02): R-03, R-04.
CREATE TABLE invitation (
    invitation_id        UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    workspace_id         UUID NOT NULL REFERENCES workspace (workspace_id),
    email                TEXT NOT NULL,
    role                 TEXT NOT NULL,
    invited_by_member_id UUID NOT NULL REFERENCES member (member_id),
    status               TEXT NOT NULL DEFAULT 'PENDING',
    CONSTRAINT invitation_role_ck CHECK (role IN
        ('WORKSPACE_ADMINISTRATOR', 'PROJECT_MANAGER', 'TEAM_MEMBER', 'VIEWER')),
    CONSTRAINT invitation_status_ck CHECK (status IN ('PENDING', 'ACCEPTED'))
);

-- Project (CMP-04): R-05, R-06. Optional fields per DA-03; archive flag per DA-11.
CREATE TABLE project (
    project_id      UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    workspace_id    UUID NOT NULL REFERENCES workspace (workspace_id),
    name            TEXT NOT NULL,
    description     TEXT,
    owner_member_id UUID REFERENCES member (member_id),
    start_date      DATE,
    due_date        DATE,
    is_archived     BOOLEAN NOT NULL DEFAULT FALSE
);

-- ProjectMember (CMP-04): resolves Project and Member (R-07, R-08).
CREATE TABLE project_member (
    project_id UUID NOT NULL REFERENCES project (project_id),
    member_id  UUID NOT NULL REFERENCES member (member_id),
    CONSTRAINT project_member_pk PRIMARY KEY (project_id, member_id)
);

-- Task (CMP-05): R-09, R-10, R-11. One owner (FR-10, BR-09); optional fields per DA-04.
CREATE TABLE task (
    task_id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    project_id           UUID NOT NULL REFERENCES project (project_id),
    title                TEXT NOT NULL,                                    -- BR-10
    description          TEXT,
    owner_member_id      UUID NOT NULL REFERENCES member (member_id),
    due_date             DATE,
    status               TEXT NOT NULL DEFAULT 'TO_DO',                     -- BR-11
    created_by_member_id UUID NOT NULL REFERENCES member (member_id),       -- BR-12
    CONSTRAINT task_status_ck CHECK (status IN ('TO_DO', 'IN_PROGRESS', 'DONE'))
);

-- Comment (CMP-07): R-12, R-13. Cascades with its task (DA-05).
CREATE TABLE comment (
    comment_id       UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    task_id          UUID NOT NULL REFERENCES task (task_id) ON DELETE CASCADE,
    author_member_id UUID NOT NULL REFERENCES member (member_id),
    body             TEXT NOT NULL,
    created_at       TIMESTAMPTZ NOT NULL DEFAULT now()                    -- DA-07
);

-- Notification (CMP-08): R-14, R-15, R-16. Cascades with its task (DA-05).
CREATE TABLE notification (
    notification_id     UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    recipient_member_id UUID NOT NULL REFERENCES member (member_id),
    type                TEXT NOT NULL,
    task_id             UUID NOT NULL REFERENCES task (task_id) ON DELETE CASCADE,
    comment_id          UUID REFERENCES comment (comment_id),
    created_at          TIMESTAMPTZ NOT NULL DEFAULT now(),                -- DA-07
    CONSTRAINT notification_type_ck CHECK (type IN ('TASK_ASSIGNED', 'COMMENT_ADDED')),
    -- comment_id is set exactly when the type is "comment added".
    CONSTRAINT notification_comment_ck CHECK ((type = 'COMMENT_ADDED') = (comment_id IS NOT NULL)),
    -- R-16: a comment triggers at most one notification.
    CONSTRAINT notification_comment_uk UNIQUE (comment_id)
);

-- Feedback (CMP-10): R-17.
CREATE TABLE feedback (
    feedback_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    member_id   UUID NOT NULL REFERENCES member (member_id),
    message     TEXT NOT NULL,
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now()                         -- DA-07
);

-- PersonalDataRequest (CMP-10): R-18, linked to the account (DA-10); status per DA-06.
CREATE TABLE personal_data_request (
    request_id   UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    account_id   UUID NOT NULL REFERENCES account (account_id),
    type         TEXT NOT NULL,
    status       TEXT NOT NULL DEFAULT 'RECEIVED',
    requested_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    completed_at TIMESTAMPTZ,
    CONSTRAINT pdr_type_ck CHECK (type IN ('COPY', 'DELETION')),
    CONSTRAINT pdr_status_ck CHECK (status IN ('RECEIVED', 'COMPLETED'))
);
